      <div class="touch-controls" id="touch-controls" hidden aria-label="触屏控制"><div class="touch-direction"><button data-touch="left" aria-label="向左">${f("arrowLeft")}</button><button data-touch="right" aria-label="向右">${f("arrow")}</button></div><button class="touch-interact" data-touch="interact" aria-label="进入星门">E</button><button class="touch-awaken" data-touch="overdrive" aria-label="星陨觉醒">${f("star")}</button><div class="touch-actions"><button data-touch="dash" class="touch-dash" aria-label="闪避">${f("bolt")}</button><button data-touch="attack" class="touch-attack" aria-label="攻击">${f("blade")}</button><button data-touch="jump" class="touch-jump" aria-label="跳跃">${f("jump")}</button></div></div>
